Here is the complete and idiomatic Rust implementation using `Tokio` and the `lru` crate. The implementation avoids `unsafe` blocks in the provided code, prevents `.clone()` on the hot path (using `&str` for lookups), and runs the async eviction in a Tokio background task.

Note on Weak References: The original TypeScript code held both a strong reference (in `entries`) and a `WeakRef` to the same object, meaning the JavaScript garbage collector would never actually collect the object while it was in the cache. In Rust, we rely on deterministic memory management. To closely match the intended design pattern, the cache stores the values directly, and memory is freed immediately upon eviction.

### `Cargo.toml`
```toml
[package]
name = "async_lru_cache"
version = "0.1.0"
edition = "2021"

[dependencies]
tokio = { version = "1.32", features = ["rt", "time", "macros", "sync", "rt-multi-thread"] }
lru = "0.12"
```

### `src/lib.rs`
```rust
use lru::LruCache;
use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tokio::task::JoinHandle;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EvictReason {
    Expired,
    Lru,
    Memory,
}

pub struct CacheEntry<V> {
    pub value: V,
    pub expires_at: Instant,
    pub size: usize,
    pub last_accessed: Instant,
    pub access_count: usize,
}

pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl: Duration,
    pub max_memory_bytes: usize,
    pub eviction_check_interval: Duration,
    pub on_evict: Option<Arc<dyn Fn(&str, EvictReason) + Send + Sync>>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl: Duration::from_secs(60),
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval: Duration::from_secs(5),
            on_evict: None,
        }
    }
}

#[derive(Default, Clone)]
pub struct CacheStats {
    pub hits: usize,
    pub misses: usize,
    pub evictions: usize,
    pub expirations: usize,
    pub size: usize,
    pub memory: usize,
}

struct CacheState<V> {
    entries: LruCache<String, CacheEntry<V>>,
    config: CacheConfig,
    current_memory: usize,
    stats: CacheStats,
}

impl<V> CacheState<V> {
    fn evict_lru(&mut self, reason: EvictReason) {
        if let Some((k, v)) = self.entries.pop_lru() {
            self.current_memory -= v.size;
            if reason == EvictReason::Expired {
                self.stats.expirations += 1;
            } else {
                self.stats.evictions += 1;
            }
            if let Some(cb) = &self.config.on_evict {
                cb(&k, reason);
            }
        }
    }

    fn delete(&mut self, key: &str, reason: EvictReason) -> bool {
        if let Some(entry) = self.entries.pop(key) {
            self.current_memory -= entry.size;
            if reason == EvictReason::Expired {
                self.stats.expirations += 1;
            } else {
                self.stats.evictions += 1;
            }
            if let Some(cb) = &self.config.on_evict {
                cb(key, reason);
            }
            true
        } else {
            false
        }
    }
}

pub struct AsyncLruCache<V> {
    state: Arc<Mutex<CacheState<V>>>,
    eviction_task: Arc<Mutex<Option<JoinHandle<()>>>>,
}

impl<V: Send + 'static> AsyncLruCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        let max_entries = NonZeroUsize::new(config.max_entries.max(1)).unwrap();
        let state = CacheState {
            entries: LruCache::new(max_entries),
            config,
            current_memory: 0,
            stats: CacheStats::default(),
        };

        Self {
            state: Arc::new(Mutex::new(state)),
            eviction_task: Arc::new(Mutex::new(None)),
        }
    }

    pub fn get(&self, key: &str) -> Option<V>
    where
        V: Clone, // Requires Clone to return an owned value; otherwise would return a guard
    {
        let mut state = self.state.lock().unwrap();
        let now = Instant::now();

        // Check expiration first to avoid promoting expired items
        let is_expired = state
            .entries
            .peek(key)
            .map(|e| now > e.expires_at)
            .unwrap_or(false);

        if is_expired {
            state.delete(key, EvictReason::Expired);
            state.stats.misses += 1;
            return None;
        }

        if let Some(entry) = state.entries.get_mut(key) {
            entry.last_accessed = now;
            entry.access_count += 1;
            state.stats.hits += 1;
            Some(entry.value.clone())
        } else {
            state.stats.misses += 1;
            None
        }
    }

    pub fn put(&self, key: String, value: V, ttl: Option<Duration>, size: Option<usize>) {
        let mut state = self.state.lock().unwrap();
        let size = size.unwrap_or(8); // Default fallback size for estimation
        let ttl = ttl.unwrap_or(state.config.default_ttl);
        let max_memory = state.config.max_memory_bytes;

        if let Some(old) = state.entries.peek(&key) {
            state.current_memory -= old.size;
        }

        while state.current_memory + size > max_memory && !state.entries.is_empty() {
            state.evict_lru(EvictReason::Memory);
        }

        let entry = CacheEntry {
            value,
            expires_at: Instant::now() + ttl,
            size,
            last_accessed: Instant::now(),
            access_count: 0,
        };

        state.current_memory += size;
        if let Some(old) = state.entries.push(key, entry) {
            state.current_memory -= old.size;
        }
    }

    pub fn delete(&self, key: &str, reason: EvictReason) -> bool {
        let mut state = self.state.lock().unwrap();
        state.delete(key, reason)
    }

    pub fn has(&self, key: &str) -> bool {
        let mut state = self.state.lock().unwrap();
        let now = Instant::now();
        if let Some(entry) = state.entries.peek(key) {
            if now > entry.expires_at {
                state.delete(key, EvictReason::Expired);
                false
            } else {
                true
            }
        } else {
            false
        }
    }

    pub fn size(&self) -> usize {
        self.state.lock().unwrap().entries.len()
    }

    pub fn memory_usage(&self) -> usize {
        self.state.lock().unwrap().current_memory
    }

    pub fn get_stats(&self) -> CacheStats {
        let state = self.state.lock().unwrap();
        let mut stats = state.stats.clone();
        stats.size = state.entries.len();
        stats.memory = state.current_memory;
        stats
    }

    pub fn clear(&self) {
        let mut state = self.state.lock().unwrap();
        state.entries.clear();
        state.current_memory = 0;
    }

    pub fn start_eviction_loop(&self) {
        let mut task_guard = self.eviction_task.lock().unwrap();
        if task_guard.is_some() {
            return;
        }

        let state_clone = Arc::clone(&self.state);
        let interval = state_clone.lock().unwrap().config.eviction_check_interval;

        let handle = tokio::spawn(async move {
            let mut ticker = tokio::time::interval(interval);
            loop {
                ticker.tick().await;
                let mut state = state_clone.lock().unwrap();
                let now = Instant::now();
                let mut expired_keys = Vec::new();

                for (k, v) in state.entries.iter() {
                    if now > v.expires_at {
                        expired_keys.push(k.clone());
                    }
                }

                for key in expired_keys {
                    state.delete(&key, EvictReason::Expired);
                }
            }
        });

        *task_guard = Some(handle);
    }

    pub fn stop_eviction_loop(&self) {
        let mut task_guard = self.eviction_task.lock().unwrap();
        if let Some(handle) = task_guard.take() {
            handle.abort();
        }
    }
}

impl<V> Drop for AsyncLruCache<V> {
    fn drop(&mut self) {
        self.stop_eviction_loop();
    }
}
