### `src/main.rs`
```rust
use async_lru_cache::{AsyncLruCache, CacheConfig};
use std::time::Duration;

#[tokio::main]
async fn main() {
    println!("Run `cargo test` to execute the cache tests.");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_basic_get_put() {
        let config = CacheConfig {
            max_entries: 3,
            ..Default::default()
        };
        let cache = AsyncLruCache::<String>::new(config);

        cache.put("a".into(), "hello".into(), None, None);
        assert_eq!(cache.get("a").unwrap(), "hello");
        assert_eq!(cache.size(), 1);
    }

    #[tokio::test]
    async fn test_lru_eviction() {
        let config = CacheConfig {
            max_entries: 3,
            ..Default::default()
        };
        let cache = AsyncLruCache::<String>::new(config);

        cache.put("a".into(), "hello".into(), None, None);
        cache.put("b".into(), "world".into(), None, None);
        cache.put("c".into(), "foo".into(), None, None);
        cache.put("d".into(), "bar".into(), None, None); // Should evict 'a'

        assert!(!cache.has("a"), "LRU eviction failed");
        assert!(cache.has("d"), "Newest item not kept");
    }

    #[tokio::test]
    async fn test_ttl_expiration() {
        let config = CacheConfig {
            max_entries: 3,
            ..Default::default()
        };
        let cache = AsyncLruCache::<String>::new(config);

        cache.put(
            "x".into(),
            "temp".into(),
            Some(Duration::from_millis(50)),
            None,
        );
        tokio::time::sleep(Duration::from_millis(80)).await;
        assert_eq!(cache.get("x"), None, "TTL expired item was retrieved");
    }

    #[tokio::test]
    async fn test_access_order() {
        let config = CacheConfig {
            max_entries: 3,
            ..Default::default()
        };
        let cache = AsyncLruCache::<String>::new(config);

        cache.put("1".into(), "one".into(), None, None);
        cache.put("2".into(), "two".into(), None, None);
        cache.put("3".into(), "three".into(), None, None);

        // Access '1', making '2' the LRU
        cache.get("1");

        // Should evict '2'
        cache.put("4".into(), "four".into(), None, None);

        assert!(!cache.has("2"), "Access order eviction failed");
        assert!(cache.has("1"), "Accessed item was not kept");
    }

    #[tokio::test]
    async fn test_eviction_loop() {
        let config = CacheConfig {
            max_entries: 10,
            default_ttl: Duration::from_millis(50),
            eviction_check_interval: Duration::from_millis(30),
            ..Default::default()
        };
        let cache = AsyncLruCache::<String>::new(config);

        cache.put("e1".into(), "val1".into(), None, None);
        cache.start_eviction_loop();

        tokio::time::sleep(Duration::from_millis(150)).await;
        assert!(!cache.has("e1"), "Eviction loop did not clear expired item");

        cache.stop_eviction_loop();
    }
}
